-- =====================================================================
-- LACHOI product catalogue (2025 Ver 4.0): 114 models, 31 series.
-- Run once in Supabase → SQL Editor. Safe to run again: it updates existing rows by SKU.
-- Photos are in /public/products/lachoi/ (served by the website, not Supabase Storage).
-- =====================================================================

-- 1) Feature bullet list on products (shown on the product page)
alter table products add column if not exists features jsonb not null default '[]'::jsonb;

-- 2) Make sure the brand and categories exist
insert into brands (name, slug, website_url) values ('Lachoi', 'lachoi', 'https://www.lachoitech.com/')
on conflict (slug) do nothing;
insert into categories (name, slug, sort_order) values ('Equipment', 'equipment', 5), ('Life Science', 'life-science', 4)
on conflict (slug) do nothing;

-- 3) Hide the old one-line-per-series LACHOI placeholders (replaced by the models below)
update products set is_active = false where sku like 'LCH-EQU-%';

-- 4) Products (one per model)
insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('LCS-MSA-D', 'Magnetic Stirrer LCS-MSA-D', 'lachoi-magnetic-stirrer-lcs-msa-d', 'MSA series magnetic stirrer is a laboratory instrument designed for mixing low-viscosity liquids and solid-liquid mixtures, with optional heating capabilities. Its integrated temperature control system enables precise thermal regulation to maintain optimal reaction conditions.', '[["Model", "LCS-MSA-D"], ["Power Supply", "AC220V 50Hz"], ["Power (W)", "50"], ["Display Mode", "LCD"], ["Motor Type", "Brushless DC motor"], ["Speed Range (rpm)", "50~2000"], ["Speed Control Accuracy", "±10 rpm"], ["Bidirectional Rotation", "Yes"], ["Timing Range", "1~99h59min"], ["Max. Stirring Volume (H₂O, L)", "20"], ["Hotplate Material", "Cast aluminum + ceramic corrosion-resistant coating"], ["Working Dimensions (mm)", "170×170"], ["Stirring Bar (mm)", "φ10×40"], ["Programming", "6-stage"], ["Net Weight (kg)", "2.58"], ["Product Dimensions (mm)", "290×188×85"]]', '["Optional bidirectional rotation", "High-strength stir bar with anti-jump design", "PT1000 precision temperature control", "Multi-material hotplates (ceramic-coated aluminum / Teflon-coated graphite / glass-ceramic)", "Residual heat warning and dual over-temperature protection", "Brushless DC motor: high torque, low noise, maintenance-free", "RS232 interface for software-based remote control", "Stirring bar jump detection with auto-recovery", "Programmable mode (up to 6 programs)"]', 'equipment', '/products/lachoi/msa-d-h-hd.jpg'),
