  ('LCS-HET-25DT', 'High Speed Homogenizer LCS-HET-25DT', 'lachoi-high-speed-homogenizer-lcs-het-25dt', 'HET series high-speed homogenizer incorporates advanced manufacturing technology. Driven by a high-speed brushless motor, its dispersing tool efficiently shears, disperses and emulsifies samples, meeting demanding application needs in biopharmaceuticals, dairy homogenization and other critical experimental processes.', '[["Model", "LCS-HET-25DT"], ["Power Supply", "AC220V 50Hz"], ["Power (W)", "1050"], ["Speed Range (rpm)", "5000~26000"], ["Timing Range", "1~99h59min"], ["Processing Volume (H₂O, mL)", "φ25: 7000"], ["Max. Processing Viscosity (mPa·s)", "φ25: 3500"], ["Dispersing Tool (mm)", "φ25×216"], ["Immersion Depth of Dispersing Tool (mm)", "62~147"], ["Dispersing Tool Material", "SUS316L"], ["Temp. Measurement Range (°C)", "-10~200"], ["Net Weight (kg)", "10.5"], ["Product Dimensions (mm)", "360×380×638"]]', '["PID closed-loop control for precise speed regulation", "Dual stainless steel support stands", "Timing, continuous operation modes and sample over-temperature protection", "High-voltage brushless motor (high torque, long service life)", "Motor stall and overload protection", "Multi-function encoder speed adjustment", "Three interchangeable dispersing tools for diverse experimental requirements", "316 stainless steel serrated blade (corrosion-resistant, high shear force)"]', 'equipment', '/products/lachoi/het.jpg'),
  ('LACHOI-DT-12', 'Homogenizer Dispersing Tool Φ12', 'lachoi-homogenizer-dispersing-tool-12', 'The homogenizer dispersing tool achieves efficient dispersion and homogenization through its high-speed rotor-stator structure, which delivers intense shear forces. Made of 316 stainless steel, corrosion-resistant and easy to disassemble and clean. Do not run it dry: the sample liquid level must cover the lower holes of the work head without exceeding the upper holes.', '[["Model", "LACHOI-DT-12"], ["Dispersing Tool (mm)", "φ12×200"], ["Processing Volume (H₂O, mL)", "200"], ["Speed Range (rpm)", "9000~26000"], ["Max. Processing Viscosity (mPa·s)", "500"], ["Stator Diameter (mm)", "Φ12"], ["Dispersing Tool Material", "316 stainless steel"], ["Bearing Material", "PTFE"], ["Immersion Depth (mm)", "40~90"]]', '[]', 'equipment', '/products/lachoi/dispersing-tool.jpg'),
